window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"GkZFomdIKD8","speaker":"Cardinal Pietro Parolin","role":"Secretary of State","country":"Holy See","region":"Europe","url":"https://www.youtube.com/watch?v=GkZFomdIKD8","date":"20260926","title":"🇻🇦 Holy See - Secretary of State Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1232,"words":2251,"counts":{"claims":28,"promises":1,"attacks":0},"topics":[{"topic":"Venezuela economy","share":0.0724,"seconds":89},{"topic":"Ukraine war","share":0.0666,"seconds":82},{"topic":"Disarmament","share":0.0655,"seconds":81},{"topic":"Azerbaijan-Armenia peace","share":0.0645,"seconds":79},{"topic":"Lebanon trilateral agreement","share":0.0643,"seconds":79},{"topic":"Rohingya crisis","share":0.0615,"seconds":76},{"topic":"AI lethal force","share":0.0608,"seconds":75},{"topic":"Haiti instability","share":0.0601,"seconds":74},{"topic":"Diplomacy ethics","share":0.0564,"seconds":69},{"topic":"South Sudan crisis","share":0.0532,"seconds":66},{"topic":"Lethal autonomous weapons","share":0.0517,"seconds":64},{"topic":"Religious freedom","share":0.0506,"seconds":62},{"topic":"DRC terrorism","share":0.0502,"seconds":62},{"topic":"UN trust","share":0.0502,"seconds":62},{"topic":"Ceremony","share":0.0501,"seconds":62},{"topic":"Gulf conflict","share":0.0495,"seconds":61},{"topic":"DRC crisis","share":0.0488,"seconds":60},{"topic":"War and peace","share":0.0236,"seconds":29}],"timeline":[[1,62,"Ceremony"],[65,126,"UN trust"],[129,198,"Diplomacy ethics"],[200,264,"Lethal autonomous weapons"],[267,342,"AI lethal force"],[343,424,"Disarmament"],[426,488,"Religious freedom"],[490,572,"Ukraine war"],[573,653,"Lebanon trilateral agreement"],[655,716,"Gulf conflict"],[718,793,"Rohingya crisis"],[795,860,"South Sudan crisis"],[862,922,"DRC crisis"],[924,985,"DRC terrorism"],[987,1076,"Venezuela economy"],[1077,1151,"Haiti instability"],[1153,1232,"Azerbaijan-Armenia peace"],[1234,1263,"War and peace"]],"stances":{"Ceremony":"Cardinal Pietro Parolin extends greetings from Pope Leo the 14th and congratulates the Assembly President on their election.","UN trust":"Cardinal Pietro Parolin states that mutual trust among members is essential for the effectiveness of international institutions and describes restoring trust as an urgent moral and political necessity.","Diplomacy ethics":"Cardinal Pietro Parolin emphasizes that diplomacy must be guided by peace, justice, and truth while rejecting the use of force and upholding human dignity.","Lethal autonomous weapons":"Cardinal Pietro Parolin argues that lethal autonomous weapon systems must be governed by moral criteria ensuring human accountability and the ability to reconstruct decision-making processes.","AI lethal force":"Cardinal Pietro Parolin asserts that the use of lethal force must not be delegated to automated processes and requires human responsibility.","Disarmament":"Cardinal Pietro Parolin states that disarmament is a necessary vehicle for restoring trust and peace, asserting that true peace is impossible without a genuine common resolve for it.","Religious freedom":"Cardinal Pietro Parolin asserts that religious freedom is an essential human right and condemns the discrimination and violence faced by Christians, while emphasizing that defending one community's freedom strengthens the freedom of all.","Ukraine war":"The Holy See calls for strict observance of international humanitarian law and urges an immediate end to hostilities to pave the way for diplomacy.","Lebanon trilateral agreement":"Cardinal Pietro Parolin welcomes the trilateral framework agreement but expresses serious concern regarding implementation difficulties and calls for full respect of its terms.","Gulf conflict":"Cardinal Pietro Parolin expresses deep concern over the spread of conflict in the Gulf region and its impact on civilians, maritime routes, and the global economy, while calling for dialogue.","Rohingya crisis":"Cardinal Pietro Parolin calls for an end to the suffering of the Rohingya people and their safe return to their homeland.","South Sudan crisis":"Cardinal Pietro Parolin urges immediate dialogue and prioritization of national well-being over partisan interests to address the humanitarian catastrophe.","DRC crisis":"Cardinal Pietro Parolin expresses concern over the protracted crisis in the Democratic Republic of Congo and calls for urgent protection of workers, unimpeded aid access, and community reconciliation.","DRC terrorism":"Cardinal Pietro Parolin expresses concern over terrorist attacks in the DRC and Gulf of Guinea, emphasizing that responses must go beyond military action to include prevention of radicalization and social cohesion.","Venezuela economy":"The Holy See encourages efforts to restore democratic order through peaceful means and emphasizes the urgent need for economic recovery to benefit the population.","Haiti instability":"The Holy See encourages Haitians to prioritize dialogue and calls on the international community to support the country's journey towards peace and democracy.","Azerbaijan-Armenia peace":"The Holy See encourages Azerbaijan and Armenia to consolidate the process of achieving a stable and lasting peace in the South Caucasus.","War and peace":"Cardinal Pietro Parolin states that war results in death and destruction while peace fosters development, and affirms the Holy See's commitment to building a better future."},"claims":[{"t":65,"quote":"As the Secretary General, His Excellency António Guterres approaches the end of his term of office, I wish also to thank him for his service to the United Nations and wish him well.","topic":"UN trust","kind":"fact"},{"t":96,"quote":"this year's theme, \"Restoring Trust, Managing Transformation, a United Nations that delivers for all,\" is not merely aspirational, it is an urgent, moral, and political","topic":"UN trust","kind":"fact"},{"t":129,"quote":"Pope Leo identifies three essential words that must guide diplomacy. Peace, justice, and truth.","topic":"Diplomacy ethics","kind":"fact"},{"t":140,"quote":"He warns us against the return of a diplomacy of force and reaffirms the indispensable role of multilateral","topic":"Diplomacy ethics","kind":"fact"},{"t":167,"quote":"From this flows the sacredness of life from conception to natural death, as well as the imperative to safeguard the human person","topic":"Diplomacy ethics","kind":"fact"},{"t":200,"quote":"The control of these powerful tools must not remain in the hands of a select few.","topic":"Lethal autonomous weapons","kind":"fact"},{"t":211,"quote":"In particular, the development of lethal autonomous weapon system raises profound moral questions.","topic":"Lethal autonomous weapons","kind":"fact"},{"t":304,"quote":"the world has spiraled into violence that has progressively spread and continually open opening up new theaters of war","topic":"AI lethal force","kind":"fact"},{"t":343,"quote":"Peace is first a gift, the gift of the risen Christ, yet an active and demanding gift.","topic":"Disarmament","kind":"fact"},{"t":374,"quote":"No true peace is possible without genuine common resolve for disarmament.","topic":"Disarmament","kind":"fact"},{"t":440,"quote":"Tragically, Christians in many parts of the world continue to suffer discrimination, violence, and outright","topic":"Religious freedom","kind":"fact"},{"t":490,"quote":"After more than 4 years of war in Ukraine, the death toll continues to Faced with this tragedy","topic":"Ukraine war","kind":"fact"},{"t":573,"quote":"The Holy See welcomes the the of the trilateral framework agreement between the United States, Israel, and aimed at stabilizing the southern borders of the Republic of Lebanon and achieving a just and lasting peace.","topic":"Lebanon trilateral agreement","kind":"fact"},{"t":590,"quote":"This agreement in itself represent a significant development.","topic":"Lebanon trilateral agreement","kind":"fact"},{"t":655,"quote":"The Holy See is following with deep concern the situation in the Gulf region where the conflict has gradually spread and the violence shows no signs of","topic":"Gulf conflict","kind":"fact"},{"t":667,"quote":"In particular, the Holy See cannot remain silent about the dramatic impact that this conflict is having on vulnerable civilian populations who are being driven into hunger and forced displacement and were living in barely sustainable","topic":"Gulf conflict","kind":"fact"},{"t":737,"quote":"hundreds of thousands of Rohingya, who for more than 90 years now suffer not only from the tragedy of but also have been subjected to inhumane and deadly circumstances","topic":"Rohingya crisis","kind":"fact"},{"t":795,"quote":"Faced with an unprecedented humanitarian catastrophe, all parties are urged to initiate, without delay, a sincere constructive dialogue with the support of the international community to facilitate assistance to the population and assure stability and peace.","topic":"South Sudan crisis","kind":"fact"},{"t":843,"quote":"The Holy See is following with deep concern the humanitarian crisis currently unfolding in certain areas of where outbreaks of violence and extreme weather events are exacerbating the population's already precarious living conditions.","topic":"South Sudan crisis","kind":"fact"},{"t":875,"quote":"The situation in the Democratic Republic of Congo is of concern to the Holy See, particularly the protracted crisis in the east of the country and the Ebola","topic":"DRC crisis","kind":"fact"},{"t":926,"quote":"terrorist attacks, especially North Kivu and Ituri, which repeatedly target the civilian population, including Christian communities, involving killings, abduction, and the destruction of villages and church structures.","topic":"DRC terrorism","kind":"fact"},{"t":944,"quote":"The Holy See notes with concern the advance of jihadist groups from the towards the coastal countries of the Gulf of Guinea.","topic":"DRC terrorism","kind":"fact"},{"t":978,"quote":"The province of Cabo Delgado in Mozambique remains destabilized after nine years of armed conflict.","topic":"DRC terrorism","kind":"number"},{"t":1011,"quote":"In Venezuela, the Holy See encourages every effort aimed at the full restoration of democratic order through peaceful, inclusive means that respect national sovereignty","topic":"Venezuela economy","kind":"fact"},{"t":1039,"quote":"the sometimes difficult faced by detainees in Venezuela, as well as the suffering endured by their families, continue to give rise to humanitarian concern","topic":"Venezuela economy","kind":"fact"},{"t":1077,"quote":"The country is currently experiencing a period of serious political, institutional, and social instability, as well as a dramatic humanitarian","topic":"Haiti instability","kind":"fact"},{"t":1153,"quote":"The Holy See encourages Azerbaijan and Armenia to consolidate the process of achieving a stable and lasting peace in the South Caucasus.","topic":"Azerbaijan-Armenia peace","kind":"fact"},{"t":1234,"quote":"War brings only death and destruction, whereas peace brings development","topic":"War and peace","kind":"fact"}],"promises":[{"t":1242,"quote":"The Holy See will continue to play its part in building a better future for all","topic":"War and peace","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Ceremony","text":"The Assembly will hear an address by His Eminence Cardinal Pietro Parolin, Secretary of State of the Holy See. I request protocol to escort His Eminence and invite him to address the &gt;&gt; Mr. President, I am honored to extend to you and to the distinguished representatives of the nations assembled here the warm greetings of His Holiness Pope Leo the 14th, while also congratulating Your Excellency on your election as President of this esteemed Assembly."},{"t":65,"topic":"UN trust","text":"As the Secretary General, His Excellency António Guterres approaches the end of his term of office, I wish also to thank him for his service to the United Nations and wish him well. Mr. President, in a world marked by rapid technological change, environmental threats, renewed conflicts, and deepening fractures in the international order, this year's theme, \"Restoring Trust, Managing Transformation, a United Nations that delivers for all,\" is not merely aspirational, it is an urgent, moral, and political Every international institution, beyond its legal framework requires mutual trust among its members to be effective. Moreover, trust is an ongoing process."},{"t":129,"topic":"Diplomacy ethics","text":"Pope Leo identifies three essential words that must guide diplomacy. Peace, justice, and truth. He warns us against the return of a diplomacy of force and reaffirms the indispensable role of multilateral Mr. President, the human person remains at the measure of all progress. At the earth of this conviction start the acknowledgement of the inviolable God-given dignity of every human person. From this flows the sacredness of life from conception to natural death, as well as the imperative to safeguard the human person, and that every society that aspires to be regarded as civilized has a duty to Pope Leo addressed in his first encyclical letter the new technological which he does not reject, but calls for its ethical ordering."},{"t":200,"topic":"Lethal autonomous weapons","text":"The control of these powerful tools must not remain in the hands of a select few. They must serve humanity, not the other way around. In particular, the development of lethal autonomous weapon system raises profound moral questions. In this critical domain Pope Leo provides clear criteria for discernment. The first concerns personal The second pertains to the moral time frame for making judgments. The third is the protection of These criteria give rise to certain not negotiable requirements. First of all, systems used in war setting must guarantee the possibility of retracing and reconstructing decision-making processes so that accountability and blame are not collapsed into the machine."},{"t":267,"topic":"AI lethal force","text":"&gt;&gt; Second, the decision to use a lethal force cannot be delegated to opaque or automated processes, but must remain under effective, self-aware, and responsible human Finally, it is imperative to establish a shared framework also at international in order to curb the technological arms race and ensure robust protection for civilians and the infrastructures necessary for their survival. For some years now, the world has spiraled into violence that has progressively spread and continually open opening up new theaters of war. The Holy See strongly emphasized the urgent need for an immediate and total cessation of hostility as a prerequisite for any serious engage engagement in restoring and building the At the same time, it is necessary to consider that peace is not a negative that is the mere absence of war."},{"t":343,"topic":"Disarmament","text":"Peace is first a gift, the gift of the risen Christ, yet an active and demanding gift. It is built in the heart of every person and is an integral part of the collective memory of every community as well as humanity's heritage. In the effort of to restoring trust and peace, disarmament is therefore not an optional ideal, but a necessary vehicle. No true peace is possible without genuine common resolve for disarmament. Mr. President, the dignity of the person finds concrete expression in the fundamental human rights and freedoms, which are inviolable since they are inherent in the human person and in human dignity. Particular attention must to be paid to those categories of persons most at those in the womb, the elderly, the disabled, the sick, refugees and migrants, the unemployed, the marginalized, the lonely, and those living under condition of extreme poverty, violence, or conflict."},{"t":426,"topic":"Religious freedom","text":"Among these fundamental rights, religious freedom occupies a privileged It is not a secondary liberty, but an essential dimension of the human person. Tragically, Christians in many parts of the world continue to suffer discrimination, violence, and outright And while condemning all forms of religious discrimination, the Holy See raises its voice on behalf of these brothers and sisters, not in a spirit of exclusive advocacy, but because the defense of any any one community's freedom strengthens the freedom of all. Mr. President, the passing of time does not make a war any less intolerable. Rather, it makes the responsibility of those who can end or help bring it to an end all the more grave."},{"t":490,"topic":"Ukraine war","text":"After more than 4 years of war in Ukraine, the death toll continues to Faced with this tragedy, the Holy See, while calling for strict observance of the international humanitarian law, highlights the urgent necessity to bring hostilities to an end and paving way for diplomacy. The Holy See encourages every initiative aimed at achieving an immediate, complete, and effective ceasefire. The Holy See reiterates its call for an end to the ongoing violence against the Palestinian civilian population in the West Bank, particularly the escalation of hostilities, home demolition, and movement restriction, driving the display displacement of Palestinian communities. On the situation in Gaza, the Holy See remains concerned about the dire humanitarian humanitarian crisis, the widespread destruction, mass displacement, and the severe persistent In this regard, urges the international community to work towards advancing the two-state solution with a view to bringing about a just and lasting peace."},{"t":573,"topic":"Lebanon trilateral agreement","text":"The Holy See welcomes the the of the trilateral framework agreement between the United States, Israel, and aimed at stabilizing the southern borders of the Republic of Lebanon and achieving a just and lasting peace. This agreement in itself represent a significant development. However, the Holy See expresses serious concern regarding the difficulties encountered in its implementation and call on the parties involved to respect fully and enforce the terms of the agreement through concrete actions. Respect for sovereignty and borders form the essential foundation for the implementation of the peace plan. Furthermore, the presence of Christians in Lebanon and throughout the Middle East must not only be safeguarded as the legitimate continuation of a historic but not but must also be encouraged by international community since Christian aspire to be an active force for peace, spirituality, and culture within the mosaic pool of people that make up the Levant where the Christian faith originated."},{"t":655,"topic":"Gulf conflict","text":"The Holy See is following with deep concern the situation in the Gulf region where the conflict has gradually spread and the violence shows no signs of In particular, the Holy See cannot remain silent about the dramatic impact that this conflict is having on vulnerable civilian populations who are being driven into hunger and forced displacement and were living in barely sustainable This conflict has also affected vital maritime transport routes, and energy resources that are of strategic importance to the entire global economy, which has an impact on the livelihood of persons all around the world. The Holy See strongly reiterates its appeal for the parties involved to find the courage to engage in dialogue."},{"t":718,"topic":"Rohingya crisis","text":"Only a renewed commitment to negotiation, supported by the international community, can restore the prospect of stable peace and shared development to the Gulf region. The international community must not forget the tragic plight of the hundreds of thousands of Rohingya, who for more than 90 years now suffer not only from the tragedy of but also have been subjected to inhumane and deadly circumstances. These individuals are deprived of their inherent rights in flagrant disrespect of their human dignity. Their suffering must end. The condition must be created within their homeland to allow the safe, legal, voluntary, and unhindered return. The Holy See renews its heartfelt appeal for an immediate end to the conflict in a land that has for too long been ravaged by indiscriminate violence affecting the most defenseless, starting with children and women."},{"t":795,"topic":"South Sudan crisis","text":"Faced with an unprecedented humanitarian catastrophe, all parties are urged to initiate, without delay, a sincere constructive dialogue with the support of the international community to facilitate assistance to the population and assure stability and peace. The Holy See appeals to all key figures in South Sudanese politics to prioritize the well-being of the nation over any partisan interests. Everyone, based on their own is called upon to promote action and words that contribute to reconciliation, peace, and harmony amongst all South The Holy See is following with deep concern the humanitarian crisis currently unfolding in certain areas of where outbreaks of violence and extreme weather events are exacerbating the population's already precarious living conditions."},{"t":862,"topic":"DRC crisis","text":"The Holy See urges the international community to generously commit to meeting the immediate needs of the most at risk, especially women and children. The situation in the Democratic Republic of Congo is of concern to the Holy See, particularly the protracted crisis in the east of the country and the Ebola The Holy See, while expressing full support for the peace processes in the country, encourages national dialogue and calls for the urgent protection of health and humanitarian workers, unimpeded access to aid, and the strengthening of regional cooperation to address these challenges in in integrated manner. Particular importance must be attached to reconciliation among communities as it is an indispensable condition for all a truly lasting peace."},{"t":924,"topic":"DRC terrorism","text":"Furthermore, the Holy See is preoccupied by the terrorist attacks, especially North Kivu and Ituri, which repeatedly target the civilian population, including Christian communities, involving killings, abduction, and the destruction of villages and church structures. The Holy See notes with concern the advance of jihadist groups from the towards the coastal countries of the Gulf of Guinea. The response cannot be exclusively military. It must include the prevention of radicalization, the develop- development of border areas, the education of young people, social cohesion cohesion, and interreligious dialogue, fully evaluating the role of religious communities in preventing extremism. The province of Cabo Delgado in Mozambique remains destabilized after nine years of armed conflict."},{"t":987,"topic":"Venezuela economy","text":"The Holy See, while calling for the end of the conflict, remains concerned about the sporadic episodes of violence, which prevent internally displaced persons from returning to their place of of and force them to continue living in a situation of suffering and food insecurity, with no prospects of a better future. In Venezuela, the Holy See encourages every effort aimed at the full restoration of democratic order through peaceful, inclusive means that respect national sovereignty, as well as the launch of a process of national reconciliation based on dialogue, the pursuit of the common good, and full respect for human rights and civil liberties. In this contest, the sometimes difficult faced by detainees in Venezuela, as well as the suffering endured by their families, continue to give rise to humanitarian concern and should not be The same consideration applies to the pressing need for a swift recovery of the national economy for the benefit of the entire population, the majority of which continues to endure extremely difficult living The Holy See continues to follow the situation in Haiti with great attention."},{"t":1077,"topic":"Haiti instability","text":"The country is currently experiencing a period of serious political, institutional, and social instability, as well as a dramatic humanitarian The Holy See encourages all Haitians to prioritize dialogue and the pursuit of the common good, and renews its appeal to the international community to accompany the country with determination and generosity on its arduous journey towards peace, democracy, and a renewed confidence in the future. The Holy See is closely monitoring the situation between Cuba and the United States and call and calls upon the those responsible to foster a sincere and effective dialogue so as to avoid any action that might increase the suffering of the beloved Cuban people. The Holy See is following the situation in Nicaragua with particular concern and reiterates its constant appeal to pursue a path of respectful and constructive dialogue with the country's authorities for the good of the people and the church in the country."},{"t":1153,"topic":"Azerbaijan-Armenia peace","text":"The Holy See encourages Azerbaijan and Armenia to consolidate the process of achieving a stable and lasting peace in the South Caucasus. Mr. President, the transformation the world is facing, technological, geopolitical, social, will not wait for the activity or inactivity of the United Whether it becomes a transformation that elevates the human person or one that diminishes it, depends on the choices made together in these rooms. It is imperative to disarm not only weapons, but the logic of domination, to protect the most in need, to speak the truth in charity, and to rebuild through dialogue and solidarity a multilateral order that truly delivers for all. May the international community, as the family of nations, have the courage to restore trust, the wisdom to manage a transformation justly, and the perseverance to build In this regard, the Holy See strongly urges all parties to engage in sincere negotiation to put an end to all wars and conflicts."},{"t":1234,"topic":"War and peace","text":"War brings only death and destruction, whereas peace brings development and The Holy See will continue to play its part in building a better future for all. Thank you. &gt;&gt; On behalf of the assembly, I wish to thank the Secretary of State of the Holy See. I now give the"}],"compare":[{"topic":"Artificial Intelligence","share":0.1185,"mean":0.0501,"rank":29,"others":83},{"topic":"Democratic Republic of the Congo","share":0.1042,"mean":0.0045,"rank":4,"others":6},{"topic":"International Law & Order","share":0.0842,"mean":0.0603,"rank":55,"others":102},{"topic":"Venezuela","share":0.0762,"mean":0.0047,"rank":6,"others":11},{"topic":"Russia-Ukraine War","share":0.0701,"mean":0.0351,"rank":35,"others":44},{"topic":"Nuclear Disarmament","share":0.0689,"mean":0.0037,"rank":7,"others":9},{"topic":"Armenia","share":0.0679,"mean":0.0015,"rank":2,"others":3},{"topic":"Lebanon","share":0.0677,"mean":0.003,"rank":3,"others":6}]};
